/**
 * Built-in services: health, default quota and every team's slice
 *
 * Instance administrator only (403 `instance_admin_required`). S3 holds NebulaCtrl's own data (backups), the registry the teams' images, Loki their central logs. Each team has a slice of each; slices of deleted teams stay until `purgeAt`. No key, bucket or address is returned.
 */
export const getInstanceServices = <ThrowOnError extends boolean = true>(options?: Options<GetInstanceServicesData, ThrowOnError>): RequestResult<GetInstanceServicesResponses, GetInstanceServicesErrors, ThrowOnError> => (options?.client ?? client).get<GetInstanceServicesResponses, GetInstanceServicesErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }, {
            in: 'cookie',
            name: 'nebulactrl_session',
            type: 'apiKey'
        }],
    url: '/admin/instance-services',
    ...options
});

/**
 * Set the default S3 quota of the teams
 *
 * Instance administrator only. The default applies to every team without its own quota (50 GiB until changed); the minimum is 1 GiB (422 `quota_too_small`). Lowering it below what a team already uses only blocks that team's new backups: nothing is deleted. Audited.
 */
